#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-y-1] [n-y..n-1] -> [n-y..n-1] [x..n-y-1] [0..x-1]
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int i=0; i<n-2 && (int)ops.size() < 4*n - 2; i++){
        // Find where value i+1 is
        int j = -1;
        for(int k=0;k<n;k++) if(p[k]==i+1) {j=k; break;}
        if(j == i) continue;

        // Need to move p[j] = i+1 to position i
        // Already placed: positions 0..i-1

        if(j > i) {
            // Step 1: Move element to position 0 if not already there
            if(j > 0 && j < n-1) {
                // x=j, y=n-1-j: prefix=[0..j-1], middle=[j], suffix=[j+1..n-1]
                // Wait, that's wrong. y=n-1-j means suffix is last n-1-j elements
                // After op: [suffix | middle=[j] | prefix]
                // Element at position j goes to position (n-1-j) in new array
                // Actually let me just bring it to front: x=1, y=n-j
                // But x+y = 1+n-j < n => j > 1. And we need j != 0.
                // Use x=j, y=n-j-1 (if n-j-1>0 i.e. j<n-1) and x+y=n-1<n ✓
                // After: [last n-j-1 elems] [p[j]] [first j elems]
                // p[j] is now at position n-j-1
                int x=j, y=n-j-1;
                ops.push_back({x,y});
                apply_op(p,x,y);
                j = n-j-1; // new position of our element... wait, let me recheck
                // Actually element was at index j. After op, prefix=[0..j-1], suffix=[j+1..n-1] (length n-j-1)
                // New order: suffix(n-j-1 elems) + middle(1 elem = p[j]) + prefix(j elems)
                j = n-j-1; // position of the single middle element
            }
            // Now move element from position j to position i
            if(j != i && j > 0 && j < n-1) {
                int x = i+1, y = n-j;
                if(x>0 && y>0 && x+y<n) {
                    ops.push_back({x,y});
                    apply_op(p,x,y);
                    continue;
                }
            }
            if(p[i]!=i+1) { // fallback
                j = -1; for(int k=0;k<n;k++) if(p[k]==i+1){j=k;break;}
                if(j!=i && j<n-1) { ops.push_back({j,1}); apply_op(p,j,1); }
                j = -1; for(int k=0;k<n;k++) if(p[k]==i+1){j=k;break;}
                if(j!=i && i+1<n && n-j>0 && i+1+n-j<n) { ops.push_back({i+1,n-j}); apply_op(p,i+1,n-j); }
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
